const AdmZip = require('adm-zip');
const { parseString } = require('xml2js');

const zip = new AdmZip('/workspace/testbed/docs/customer_report.docx');
const docXml = zip.readAsText('word/document.xml');

// Extract text using regex to strip XML tags
// First get w:t elements
const matches = docXml.match(/<w:t[^>]*>([^<]*)<\/w:t>/g);
if (matches) {
    let currentParagraph = '';
    const lines = [];
    // Split by paragraphs
    const paragraphs = docXml.split(/<\/w:p>/);
    for (const p of paragraphs) {
        const tMatches = p.match(/<w:t[^>]*>([^<]*)<\/w:t>/g);
        if (tMatches) {
            const text = tMatches.map(m => m.replace(/<[^>]+>/g, '')).join('');
            if (text.trim()) lines.push(text);
        }
    }
    console.log(lines.join('\n'));
} else {
    console.log('No text found');
}
"

