node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Find the LogiTech Wireless Mouse M310 product
const logitech = db.prepare(\"SELECT * FROM products WHERE name LIKE '%mouse%' OR name LIKE '%Mouse%'\").all();
for (const p of logitech) {
    console.log('--- Product:', p.name, '(ID:', p.product_id + ')');
    console.log('  Category:', p.category, '| Subcategory:', p.subcategory);
    console.log('  Brand:', p.brand, '| Price:', p.price, '| In Stock:', p.in_stock);
    console.log('  Description:', p.description);
}

console.log('\n\n=== All wireless mouse variants ===');
// Get product IDs for mouse products
const mouseProductIds = logitech.map(p => p.product_id);
for (const pid of mouseProductIds) {
    const variants = db.prepare('SELECT * FROM rt_variants WHERE product_id = ?').all(pid);
    const product = logitech.find(p => p.product_id === pid);
    console.log('\n' + product.name + ' (product_id: ' + pid + ') — ' + variants.length + ' variants:');
    for (const v of variants) {
        console.log('  item_id:', v.item_id, '| options:', v.options, '| price:', v.price, '| available:', v.available);
    }
}
"

